.stats {
  display: flex;
  gap: 0;
  overflow-x: auto;
  border-bottom: 1px solid rgba(198, 198, 205, .58);
}

.stat {
  min-width: 160px;
  padding: 10px 18px;
  border-right: 1px solid rgba(198, 198, 205, .58);
}

.stat span {
  display: block;
  color: var(--muted);
  font-size: 11px;
  line-height: 16px;
  font-weight: 800;
  letter-spacing: .05em;
  text-transform: uppercase;
}

.stat strong {
  display: block;
  color: var(--primary);
  font-size: 20px;
  line-height: 24px;
}

.toolbar {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 14px;
  background: var(--surface);
}

.toolbar label {
  flex: 0 0 auto;
  color: var(--muted);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: .05em;
  text-transform: uppercase;
}

.toolbar input {
  max-width: 270px;
}

.toolbar select {
  max-width: 180px;
}

.filters {
  overflow-x: auto;
}

.scope-strip {
  margin: 0 -14px;
  border-bottom: 1px solid rgba(198, 198, 205, .58);
}

.board {
  min-height: calc(100vh - 230px);
  display: flex;
  align-items: flex-start;
  gap: 12px;
  overflow-x: auto;
  padding: 14px 0;
}

.column {
  width: 320px;
  flex: 0 0 320px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface);
}

.column-head {
  min-height: 48px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 12px;
  border-bottom: 1px solid var(--line);
  background: var(--background);
}

.column-head h3 {
  margin: 0;
  color: var(--text);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: .05em;
  text-transform: uppercase;
}

.column-head h3 span {
  margin-left: 6px;
  color: var(--outline);
  font-weight: 500;
}

.column-head button {
  width: 28px;
  min-height: 26px;
  border: 0;
  background: transparent;
  padding: 0;
}

.column-blocked .column-head,
.column-handoff_ready .column-head {
  background: rgba(255, 218, 214, .3);
}

.column-in_progress .column-head {
  background: rgba(57, 184, 253, .18);
}

.task-card {
  margin: 10px;
  padding: 12px;
  border: 1px solid var(--line);
  border-left: 3px solid var(--outline);
  border-radius: var(--radius);
  background: var(--surface);
  cursor: pointer;
}

.task-card:hover {
  background: var(--background);
  border-color: var(--outline);
}

.task-card.status-blocked,
.task-card.status-handoff_ready {
  border-color: rgba(186, 26, 26, .42);
  border-left-color: var(--danger);
}

.task-card.status-in_progress {
  border-color: rgba(0, 101, 145, .42);
  border-left-color: var(--secondary);
}

.task-card.status-completed {
  border-left-color: var(--success);
  opacity: .72;
}

.task-card-top,
.task-card-footer,
.task-signal-row,
.item-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.task-signal-row {
  justify-content: flex-start;
  flex-wrap: wrap;
  min-height: 22px;
  margin-top: 8px;
}

.code-chip,
.repo-chip,
.pill,
.priority,
.status-badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  border: 1px solid rgba(198, 198, 205, .75);
  border-radius: 2px;
  background: var(--surface-low);
  padding: 2px 6px;
  color: var(--muted);
  font: 11px/14px "JetBrains Mono", monospace;
  letter-spacing: .02em;
}

.priority,
.status-badge {
  font-family: "Inter", sans-serif;
  font-weight: 800;
  letter-spacing: .05em;
  text-transform: uppercase;
}

.priority-high,
.priority-urgent,
.pill.red {
  border-color: rgba(186, 26, 26, .45);
  background: var(--danger-soft);
  color: var(--danger);
}

.priority-urgent {
  background: var(--danger);
  color: #fff;
}

.priority-low {
  background: var(--surface-high);
}

.pill.amber {
  border-color: rgba(173, 101, 0, .45);
  background: var(--warning-soft);
  color: #684000;
}

.card-title {
  margin-top: 10px;
  color: var(--primary);
  font-weight: 700;
}

.task-goal {
  margin: 6px 0 0;
  color: var(--muted);
  font-size: 13px;
}

.task-card-footer {
  margin-top: 10px;
  padding-top: 9px;
  border-top: 1px solid rgba(198, 198, 205, .55);
}

.avatar {
  width: 24px;
  height: 24px;
  display: grid;
  place-items: center;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--sidebar);
  color: var(--secondary-hot);
  font: 10px/1 "JetBrains Mono", monospace;
}

.grid2 {
  display: grid;
  grid-template-columns: minmax(260px, 320px) minmax(0, 1fr);
  gap: 24px;
  max-width: 1280px;
  margin: 18px auto;
}

.detail-layout {
  align-items: start;
}

.detail-stack {
  display: grid;
  gap: 18px;
}

.detail-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 16px;
}

.panel,
.section,
.item,
.mini-card {
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface);
}

.panel,
.section {
  padding: 16px;
}

.panel h2,
.section h3 {
  margin: 0 0 12px;
  padding-bottom: 10px;
  border-bottom: 1px solid var(--line);
  color: var(--primary);
  font-size: 14px;
  font-weight: 800;
  letter-spacing: .04em;
}

.detail-hero {
  display: flex;
  justify-content: space-between;
  gap: 18px;
  padding: 28px;
}

.detail-hero h2 {
  margin: 0 0 8px;
  padding: 0;
  border: 0;
  font-size: 26px;
  letter-spacing: -.02em;
}

.detail-hero p {
  max-width: 820px;
  margin: 0;
  color: var(--muted);
}

.hero-badges {
  display: flex;
  align-items: flex-start;
  gap: 8px;
}

.detail-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  padding: 10px;
}

.detail-meta span {
  border: 1px solid rgba(198, 198, 205, .65);
  border-radius: 2px;
  background: var(--surface-low);
  padding: 4px 7px;
  color: var(--muted);
  font: 12px/16px "JetBrains Mono", monospace;
}

.form {
  display: grid;
  gap: 10px;
}

.actions-panel,
.panel .form {
  gap: 10px;
}

.section.task-memory {
  grid-column: span 1;
  background: #fffef8;
}

.markdown-doc,
.log-panel,
.memory-editor,
.error-box {
  width: 100%;
  overflow: auto;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: #fffdf6;
  padding: 12px;
  color: var(--text);
  font: 13px/18px "JetBrains Mono", monospace;
  white-space: pre-wrap;
}

.error-box {
  border-color: rgba(186, 26, 26, .45);
  background: rgba(255, 218, 214, .28);
  color: var(--danger);
}

.item,
.mini-card {
  margin-top: 8px;
  padding: 10px;
}

.item.clickable,
.linkish {
  cursor: pointer;
}

.meta,
small.meta {
  color: var(--muted);
  font-size: 12px;
}

.timeline {
  display: grid;
  gap: 8px;
}

.log-line {
  padding-left: 10px;
  border-left: 2px solid var(--surface-highest);
}

.conflict-card {
  border-left: 3px solid var(--danger);
}

.conflict-tasks {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
  margin: 10px 0;
}

.actors-view,
.projects-view {
  max-width: 1280px;
}

.login {
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: 24px;
  background: var(--sidebar);
}

.login-panel {
  width: min(420px, 100%);
}

.modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 100;
  display: grid;
  place-items: center;
  background: rgba(11, 28, 48, .56);
}

.modal-card {
  width: min(680px, calc(100vw - 32px));
  display: grid;
  gap: 10px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface);
  padding: 16px;
}

.toast,
.error {
  border-color: rgba(186, 26, 26, .45);
  background: var(--danger-soft);
  color: var(--danger);
}

@media (max-width: 920px) {
  :root {
    --sidebar-width: 72px;
  }

  .sidebar-brand div:not(.brand-mark),
  .tabs button span:last-child,
  .sidebar-quick {
    display: none;
  }

  .tabs button {
    justify-content: center;
    padding: 0;
  }

  .sync-button {
    min-width: 40px;
    padding: 0;
  }

  .sync-button {
    font-size: 0;
  }

  .grid2,
  .detail-grid {
    grid-template-columns: 1fr;
  }

  .appbar {
    flex-wrap: wrap;
    height: auto;
    padding: 8px;
  }
}

