+  padding-bottom: 10px;
+  border-bottom: 1px solid var(--line);
+}
+
+.section-bar h3 {
+  display: flex;
+  align-items: center;
+  gap: 8px;
+  margin: 0;
+  color: var(--text);
+  font-size: 21px;
+  line-height: 26px;
+}
+
+.section-bar .material-symbols-outlined {
+  color: var(--secondary);
+}
+
+.infra-grid {
+  display: grid;
+  grid-template-columns: minmax(280px, 380px) minmax(0, 1fr);
+  gap: 30px;
+}
+
+.infra-main {
+  display: grid;
+  gap: 30px;
+}
+
+.project-card-list,
+.team-list {
+  border: 1px solid var(--line);
+  border-radius: var(--radius);
+  background: var(--surface);
+  overflow: hidden;
+}
+
+.project-card {
+  position: relative;
+  padding: 18px 18px 18px 20px;
+  border-bottom: 1px solid var(--line);
+}
+
+.project-card:last-child {
+  border-bottom: 0;
+}
+
+.project-card::before {
+  content: "";
+  position: absolute;
+  inset: 0 auto 0 0;
+  width: 3px;
+  background: var(--secondary-hot);
+}
+
+.project-card h4,
+.workspace-card h4,
+.handoff-card h4 {
+  margin: 0;
+  color: var(--text);
+  font-size: 16px;
+  line-height: 22px;
+}
+
+.project-card p {
+  margin: 10px 0 14px;
+  color: var(--muted);
+}
+
+.infra-meta,
+.workspace-facts {
+  display: flex;
+  flex-wrap: wrap;
+  gap: 14px;
+  color: var(--muted);
+  font-size: 12px;
+}
+
+.infra-meta span,
+.workspace-facts span {
+  display: inline-flex;
+  align-items: center;
+  gap: 5px;
+}
+
+.data-table-wrap {
+  border: 1px solid var(--line);
+  border-radius: var(--radius);
+  background: var(--surface);
+  overflow: auto;
+}
+
+.data-table {
+  width: 100%;
+  border-collapse: collapse;
+  text-align: left;
+}
+
+.data-table th {
+  border-bottom: 2px solid var(--line);
+  background: var(--surface-low);
+  padding: 10px 12px;
+  color: var(--muted);
+  font-size: 11px;
+  font-weight: 800;
+  letter-spacing: .05em;
+  text-transform: uppercase;
+}
+
+.data-table td {
+  border-bottom: 1px solid rgba(198, 198, 205, .55);
+  padding: 10px 12px;
+  vertical-align: middle;
+}
+
+.data-table tr:nth-child(even) td {
+  background: rgba(248, 249, 255, .74);
+}
+
+.data-table tr:last-child td {
+  border-bottom: 0;
+}
+
+.data-table td:first-child {
+  font-weight: 700;
+}
+
+.data-table .material-symbols-outlined {
+  margin-right: 6px;
+  color: var(--muted);
+}
+
+.mono {
+  font-family: "JetBrains Mono", monospace;
+}
+
+.status-dot {
+  width: 6px;
+  height: 6px;
+  border-radius: 999px;
+  background: var(--secondary-hot);
+}
+
+.muted-badge {
+  color: var(--muted);
+  background: var(--background);
+}
+
+.empty-cell,
+.empty-panel {
+  padding: 20px;
+  color: var(--muted);
+}
+
+.empty-panel {
+  border: 1px solid var(--line);
+  border-radius: var(--radius);
+  background: var(--surface);
+}
+
+.workspace-grid {
+  display: grid;
+  grid-template-columns: repeat(2, minmax(0, 1fr));
+  gap: 18px;
+}
+
+.workspace-card {
+  border: 1px solid var(--line);
+  border-radius: var(--radius);
+  background: var(--surface);
+  padding: 18px;
+}
+
+.workspace-card .item-head {
+  margin-bottom: 14px;
+}
+
+.workspace-card p {
+  margin: 14px 0 0;
+}
+
+.inline-create,
+.menu-create {
+  margin-top: 14px;
+}
+
+.inline-create summary,
+.menu-create summary {
+  display: inline-flex;
+  align-items: center;
+  gap: 6px;
+  border: 1px solid var(--line);
+  border-radius: var(--radius);
+  background: var(--surface);
+  padding: 7px 10px;
+  color: var(--text);
+}
+
+.inline-create .panel,
+.menu-create .panel {
+  margin-top: 10px;
+  box-shadow: none;
+}
+
+.handoff-grid {
+  display: grid;
+  grid-template-columns: repeat(2, minmax(0, 1fr));
+  gap: 18px;
+}
+
+.handoff-card {
+  position: relative;
+  display: grid;
+  gap: 14px;
+  border: 1px solid var(--line);
+  border-radius: var(--radius);
+  background: var(--surface);
+  padding: 20px 20px 20px 24px;
+  overflow: hidden;
+}
+
+.handoff-accent {
+  position: absolute;
+  inset: 0 auto 0 0;
+  width: 3px;
+  background: var(--secondary-hot);
+}
+
+.handoff-summary {
+  border: 1px solid rgba(198, 198, 205, .62);
+  border-radius: var(--radius);
+  background: var(--surface-mid);
+  padding: 12px;
+}
+
+.handoff-summary p,
+.handoff-next p {
+  margin: 6px 0 0;
+}
+
+.danger-text {
+  color: var(--danger);
+}
+
+.handoff-actions {
+  display: grid;
+  grid-template-columns: minmax(0, 1fr) auto;
+  gap: 10px;
+}
+
+.agent-action {
+  border-color: var(--secondary);
+  background: var(--secondary);
+  color: #fff;
+  box-shadow: 0 0 8px rgba(57, 184, 253, .32);
+}
+
+.agent-action:hover {
+  background: #087aaa;
+  color: #fff;
+}
+
+.settings-grid {
+  display: grid;
+  grid-template-columns: minmax(0, 2fr) minmax(320px, 1fr);
+  gap: 30px;
+}
+
+.settings-main,
+.settings-side {
+  display: grid;
+  align-content: start;
+  gap: 24px;
+}
+
+.settings-card,
+.cli-card {
+  border: 1px solid var(--line);
+  border-radius: var(--radius);
+  background: var(--surface);
+  overflow: hidden;
+}
+
+.settings-card-head {
+  display: flex;
+  align-items: center;
+  gap: 8px;
+  border-bottom: 1px solid var(--line);
+  background: var(--surface-low);
+  padding: 14px 16px;
+}
+
+.settings-card-head h3 {
+  margin: 0;
+  font-size: 20px;
+  line-height: 24px;
+}
+
+.account-body {
+  display: grid;
+  grid-template-columns: 84px minmax(0, 1fr);
+  gap: 28px;
+  padding: 26px 30px;
+}
+
+.account-avatar {
+  width: 64px;
+  height: 64px;
+  display: grid;
+  place-items: center;
+  border: 1px solid var(--line);
+  border-radius: var(--radius);
+  background: var(--surface-high);
+  color: var(--muted);
+  font-size: 25px;
+  font-weight: 800;
+}
+
+.field-grid {
+  display: grid;
+  grid-template-columns: repeat(2, minmax(0, 1fr));
+  gap: 16px;
+}
+
+.field-grid label {
+  display: grid;
+  gap: 6px;
+  color: var(--muted);
+  font-size: 11px;
+  font-weight: 800;
+  letter-spacing: .05em;
+  text-transform: uppercase;
+}
+
+.field-grid input[readonly] {
+  color: var(--text);
+}
+
+.security-row,
+.team-row,
+.notification-row {
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  gap: 16px;
+}
+
+.security-row {
+  margin-top: 18px;
+  padding-top: 18px;
+  border-top: 1px solid rgba(198, 198, 205, .55);
+}
+
+.settings-card-foot {
+  border-top: 1px solid var(--line);
+  background: var(--surface-low);
+  padding: 16px 30px;
+}
+
+.settings-card-foot .panel {
+  border: 0;
+  background: transparent;
+  padding: 0;
+}
+
+.settings-card-foot .panel h2 {
+  margin-bottom: 10px;
+}
+
+.team-list {
+  border: 0;
+  padding: 22px 30px;
+}
+
+.team-row {
+  border-bottom: 1px solid rgba(198, 198, 205, .55);
+  padding: 14px 0;
+}
+
+.team-row:first-child {
+  padding-top: 0;
+}
+
+.team-avatar {
+  width: 34px;
+  height: 34px;
+  display: grid;
+  place-items: center;
+  border-radius: var(--radius);
+  background: var(--tertiary-container, #271901);
+  color: var(--warning-soft);
+  font-weight: 800;
+}
+
+.team-avatar.light {
+  border: 1px solid var(--line);
+  background: var(--surface-high);
+  color: var(--muted);
+}
+
+.team-row+button {
+  width: 100%;
+  margin-top: 18px;
+  border-style: dashed;
+}
+
+.cli-card {
+  border-color: rgba(190, 198, 224, .45);
+  background: linear-gradient(135deg, #111a2e, #16243b);
+  color: #eaf1ff;
+}
+
+.cli-card .settings-card-head {
+  border-color: rgba(190, 198, 224, .28);
+  background: rgba(0, 0, 0, .14);
+}
+
+.cli-card p,
+.cli-card .meta {
+  color: rgba(234, 241, 255, .74);
+}
+
+.cli-card .item {
+  border-color: rgba(190, 198, 224, .28);
+  background: rgba(0, 0, 0, .22);
+}
+
+.cli-card textarea {
+  background: rgba(0, 0, 0, .34);
+  color: var(--secondary-hot);
+  font-family: "JetBrains Mono", monospace;
+}
+
+.cli-card .agent-action {
+  width: calc(100% - 32px);
+  margin: 0 16px 16px;
+}
+
+.notifications-card {
+  padding-bottom: 18px;
+}
+
+.notification-row {
+  padding: 16px 22px 0;
+}
+
+.notification-row strong {
+  color: var(--text);
+}
+
+.toggle {
+  position: relative;
+  flex: 0 0 auto;
+  width: 40px;
+  height: 22px;
+  border-radius: 999px;
+  background: var(--surface-high);
+  border: 1px solid var(--line);
+}
+
+.toggle span {
+  position: absolute;
+  top: 2px;
+  left: 2px;
+  width: 16px;
+  height: 16px;
+  border-radius: 999px;
+  background: #fff;
+  border: 1px solid var(--line);
+}
+
+.toggle.on {
+  background: var(--secondary);
+}
+
+.toggle.on span {
+  left: 20px;
+}
+
+.notifications-card a {
+  display: block;
+  margin: 18px 22px 0;
+  border-top: 1px solid rgba(198, 198, 205, .55);
+  padding-top: 16px;
+  color: var(--muted);
+  text-decoration: none;
+}
